import{i as d}from"./shared.NUUPnALZ.js";const i=document.querySelector("#config-editor"),s=document.querySelector("#config-status"),l=document.querySelector("#config-password"),n=document.querySelector("#load-config"),c=document.querySelector("#save-config");n.addEventListener("click",async e=>{e.preventDefault(),await f()});c.addEventListener("click",async e=>{e.preventDefault(),confirm("설정을 저장할까요? 작업 스크립트와 실행 환경이 즉시 바뀔 수 있습니다.")&&await u()});async function f(){const e=l.value;if(!e){t("비밀번호가 필요합니다.","error");return}n.disabled=!0,t("불러오는 중...","");try{const o=await fetch("/api/config",{headers:{"X-Builda-Config-Password":e}});if(!o.ok){const r=await o.json().catch(()=>({}));t(r.error||"설정을 불러오지 못했습니다.","error");return}const a=await o.json();i.value=a.content||"",t("","")}catch(o){t(o.message,"error")}finally{n.disabled=!1}}async function u(){const e=l.value;if(!e){t("비밀번호가 필요합니다.","error");return}c.disabled=!0,t("검증 중...","");try{const o=new URLSearchParams({content:i.value,password:e}),a=await fetch("/api/config",{method:"POST",body:o}),r=await a.json().catch(()=>({}));if(!a.ok||!r.ok)throw new Error(r.error||"설정 저장에 실패했습니다.");t("저장했습니다.","ok")}catch(o){t(o.message,"error")}finally{c.disabled=!1}}function t(e,o){s.textContent=e,s.className="editor-status"+(o?" "+o:"")}await d();t("비밀번호를 입력해 설정을 불러오세요.","");
